#
# validate.jl
#
# Validation runner of the tutor examples: pointwise comparison with the
# NESSi reference data (tutor/data, generated by .nessi/kbref/generate.sh)
# and regression checks of every example program. Each tutor/<case>
# directory also has its own validate.jl that can be run directly.
#
# Usage: julia --startup-file=no --project=. tutor/validate.jl
#

using Test
using KadanoffBaym

@testset verbose = true "KadanoffBaym: tutor validation" begin
    include(joinpath(@__DIR__, "common", "validate.jl"))
    include(joinpath(@__DIR__, "hubbard_chain", "validate.jl"))
    include(joinpath(@__DIR__, "fkm_bethe", "validate.jl"))
    include(joinpath(@__DIR__, "holstein_bethe", "validate.jl"))
    include(joinpath(@__DIR__, "holstein_impurity", "validate.jl"))
    include(joinpath(@__DIR__, "hubbard_bethe", "validate.jl"))
    include(joinpath(@__DIR__, "anderson_ness", "validate.jl"))
    include(joinpath(@__DIR__, "gw", "validate.jl"))
    include(joinpath(@__DIR__, "profiles.jl"))
end
